mapper.select:
SELECT * FROM (SELECT /*+ INDEX(C IX_ASR_RESOURCE) */ 
  FROM SMT_AUTH_SOURCE_RESOURCE C JOIN SMT_AUTH_SOURCE_COORD S ON S.ID=C.SOURCE_COORD_ID AND S.GENERATION=C.SOURCE_GENERATION
  WHERE C.RESOURCE_COORD_ID=#{resourceId} AND C.BINDING_REVISION=0 AND C.STATE!='CONVERGED' AND S.STATE!='TOMBSTONE'
    AND (C.ACTION='DELETE' OR S.ACTION='DELETE')
    AND C.SOURCE_COORD_ID > #{after}
  ORDER BY C.SOURCE_COORD_ID) WHERE ROWNUM <= #{limit}

SELECT /*+ INDEX(C IX_ASR_RESOURCE) */ MIN(C.TARGET_ID) FROM SMT_AUTH_SOURCE_RESOURCE C JOIN SMT_AUTH_SOURCE_COORD S ON S.ID=C.SOURCE_COORD_ID
  AND S.GENERATION=C.SOURCE_GENERATION WHERE C.RESOURCE_COORD_ID=#{resourceId} AND C.RESOURCE_GENERATION=#{generation}
  AND C.BINDING_REVISION=0

SELECT * FROM SMT_AUTH_SOURCE_RESOURCE WHERE SOURCE_COORD_ID=#{binding.sourceId}
  AND SOURCE_GENERATION=#{binding.sourceGeneration} AND RESOURCE_COORD_ID=#{binding.resourceId}
  AND RESOURCE_GENERATION=#{binding.resourceGeneration} AND TARGET_ID=#{binding.targetId} AND BINDING_REVISION >= 0

SELECT COUNT(*) FROM SMT_AUTH_DELETE_REQUEST Q JOIN SMT_AUTH_OPERATION_TARGET T ON T.BATCH_ID = Q.BATCH_ID
WHERE Q.ID = #{binding.requestId} AND T.ID = #{binding.targetId}
  AND Q.PARK_ID = #{source.parkId} AND Q.SUBJECT_TYPE = #{source.subjectType}
  AND Q.SOURCE_IDENTITY_KEY = #{source.id} AND Q.GENERATION = #{binding.sourceGeneration}
  AND T.PARK_ID = #{resource.parkId} AND T.SUBJECT_TYPE = #{resource.subjectType}
  AND T.SUBJECT_ID = #{resource.subjectId} AND T.DEVICE_ID = #{resource.deviceId}
  AND T.RESOURCE_TYPE = #{resource.resourceType} AND T.RESOURCE_ID = #{targetResourceId}
  AND T.ACCESS_TYPE = #{resource.accessType} AND T.OPERATION_VERSION = #{binding.resourceGeneration}
  AND Q.BATCH_ID = #{batchId}
  AND T.ACTION = #{action}
  AND EXISTS (SELECT 1 FROM SMT_AUTH_OPERATION_ATTEMPT A
    WHERE A.ID = #{binding.attemptId} AND A.TARGET_ID = T.ID AND A.ACCESS_TYPE = T.ACCESS_TYPE)

SELECT * FROM (SELECT ID,SOURCE_COORD_ID,SOURCE_GENERATION,RESOURCE_COORD_ID,RESOURCE_GENERATION,SOURCE_ROW_ID,SOURCE_FINGERPRINT,ACTION,STATE,REQUEST_ID,TARGET_ID,ATTEMPT_ID,BINDING_REVISION,SOURCE_ACTION,INTENT_KEY,INTENT_FINGERPRINT FROM SMT_AUTH_SOURCE_RESOURCE WHERE SOURCE_COORD_ID=#{sourceId}
  AND SOURCE_GENERATION=#{generation} AND BINDING_REVISION=0 AND STATE != 'CONVERGED'
  AND RESOURCE_COORD_ID > #{after}
  ORDER BY RESOURCE_COORD_ID) WHERE ROWNUM <= #{limit}
